/**
 * Shared Affected-Repositories section builders (gh-1250 dedup).
 *
 * Pure formatting helpers for the "Affected Repositories" block appended to
 * the solution field (writeSolutionAndLabels.js) and the Confluence page
 * (writeSolutionAndDiagrams.js, via the lazy require cycle-breaker). The
 * repo-table rows, the mermaid dependency graph and the JSON anchor appeared
 * identically in three formatters (Jira wiki, ADO markdown, Confluence
 * markdown) — the per-format differences are only the code-fence tokens, so
 * they live in the exported FENCES constants.
 *
 * GraalJS-compatible: var declarations, plain functions, no arrow functions.
 */

/** 'a, b' for non-empty depends_on, em-dash otherwise. */
function formatRepoDeps(r) {
    return (Array.isArray(r.depends_on) && r.depends_on.length > 0)
        ? r.depends_on.join(', ')
        : '\u2014';
}

/** GFM/wiki table rows: | # | name | reason | deps | */
function buildRepoTableRows(sorted) {
    var rows = [];
    sorted.forEach(function(r, idx) {
        rows.push('| ' + (idx + 1) + ' | ' + r.name + ' | ' + (r.reason || '') + ' | ' + formatRepoDeps(r) + ' |');
    });
    return rows;
}

/** Mermaid dependency edges ('    dep --> name'), in sorted order. */
function buildDependencyEdges(sorted) {
    var edges = [];
    sorted.forEach(function(r) {
        if (Array.isArray(r.depends_on)) {
            r.depends_on.forEach(function(dep) { edges.push('    ' + dep + ' --> ' + r.name); });
        }
    });
    return edges;
}

// Per-format code fences for the section body.
//   - jsonOpen/jsonClose are omitted for Confluence: the JSON anchor is a
//     tracker-field-only payload (createRepoTasks parses it back out of the
//     field), meaningless on a Confluence page.
var JIRA_FENCES = {
    mermaidOpen: '{code}',
    mermaidClose: '{code}',
    jsonOpen: '{code:json|title=affected_repos}',
    jsonClose: '{code}'
};

var MARKDOWN_FENCES = {
    mermaidOpen: '```mermaid',
    mermaidClose: '```',
    jsonOpen: '```json',
    jsonClose: '```'
};

var CONFLUENCE_FENCES = {
    mermaidOpen: '```mermaid',
    mermaidClose: '```'
};

/** Mermaid dependency graph block ('graph LR' + edges), only when there are edges. */
function appendMermaidEdges(lines, sorted, fenceOpen, fenceClose) {
    var edges = buildDependencyEdges(sorted);
    if (edges.length > 0) {
        lines.push('');
        lines.push(fenceOpen);
        lines.push('graph LR');
        edges.forEach(function(e) { lines.push(e); });
        lines.push(fenceClose);
    }
}

/** JSON anchor block: the machine-readable payload createRepoTasks parses. */
function appendJsonAnchor(lines, sorted, fenceOpen, fenceClose) {
    lines.push('');
    lines.push(fenceOpen);
    lines.push(JSON.stringify(sorted, null, 2));
    lines.push(fenceClose);
}

/**
 * Append the full section body for sorted repos to lines (in place): the repo
 * table rows, the mermaid dependency graph (only when there are edges) and,
 * unless fences.jsonOpen is absent (Confluence), the JSON anchor block.
 */
function appendSectionBody(lines, sorted, fences) {
    buildRepoTableRows(sorted).forEach(function(row) { lines.push(row); });
    appendMermaidEdges(lines, sorted, fences.mermaidOpen, fences.mermaidClose);
    if (fences.jsonOpen) {
        appendJsonAnchor(lines, sorted, fences.jsonOpen, fences.jsonClose);
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        formatRepoDeps: formatRepoDeps,
        buildRepoTableRows: buildRepoTableRows,
        buildDependencyEdges: buildDependencyEdges,
        appendSectionBody: appendSectionBody,
        JIRA_FENCES: JIRA_FENCES,
        MARKDOWN_FENCES: MARKDOWN_FENCES,
        CONFLUENCE_FENCES: CONFLUENCE_FENCES
    };
}

/**
 * Shared helpers for the SM-cycle "done check" postJSActions
 * (checkSubtasksDoneForBA, checkTaskStoriesDone) — gh-1250.
 *
 * Both actions run on every SM cycle and, while the items they check are not
 * all Done, remove the SM idempotency label so the SM re-triggers the check
 * on the next cycle and return the same "waiting" result shape. Extracted so
 * the lock-release block lives in one place; callers parameterize the log
 * wording and the totals.
 */

function releaseSmLock(tracker, ticketKey, removeLabel) {
    if (!ticketKey || !removeLabel) return;
    try {
        tracker.removeLabel(ticketKey, removeLabel);
        console.log('Released SM label — will re-check next cycle');
    } catch (e) {
        console.warn('Failed to remove SM label:', e);
    }
}

/**
 * Log the caller's "not done yet" message, release the SM idempotency label
 * and return the shared "waiting" result both done-check actions report.
 */
function waitingResult(tracker, ticketKey, removeLabel, logMessage, total, notDone) {
    console.log(logMessage);
    releaseSmLock(tracker, ticketKey, removeLabel);
    return { success: true, action: 'waiting', total: total, notDone: notDone, ticketKey: ticketKey };
}

/**
 * Resolve the action context both done-check actions share: ticketKey,
 * removeLabel, the project config and the tracker built from it.
 */
function resolveActionContext(params, configLoader, trackersModule) {
    var customParams = params.jobParams && params.jobParams.customParams;
    var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    return {
        ticketKey: params.ticket && params.ticket.key,
        removeLabel: customParams && customParams.removeLabel,
        projectConfig: projectConfig,
        tracker: trackersModule.createTracker(projectConfig, customParams || {})
    };
}

/**
 * Shared action() skeleton for the SM done-check postJSActions: resolves the
 * action context, runs the caller's check and, on failure, releases the SM
 * lock and returns the standard failure shape. The caller's checkFn receives
 * (tracker, projectConfig, ticketKey, removeLabel, initiator).
 */
function runDoneCheckAction(params, checkFn, scriptName, configLoader, trackersModule) {
    var ctx = resolveActionContext(params, configLoader, trackersModule);
    try {
        if (!ctx.ticketKey) throw new Error('params.ticket.key is missing');
        return checkFn(ctx.tracker, ctx.projectConfig, ctx.ticketKey, ctx.removeLabel, params.initiator);
    } catch (error) {
        console.error('❌ Error in ' + scriptName + ':', error);
        releaseSmLock(ctx.tracker, ctx.ticketKey, ctx.removeLabel);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        releaseSmLock: releaseSmLock,
        waitingResult: waitingResult,
        resolveActionContext: resolveActionContext,
        runDoneCheckAction: runDoneCheckAction
    };
}

